 const forms=FORMS[topic.level];
 topic.items.forEach((item,itemIndex)=>forms.forEach((form,formIndex)=>{
  const spanish=form[0].replace('{0}',item[0]);
  const arabic=form[1].replace('{1}',item[1]);
  lessons.push({id:`${topic.level}-${topicIndex}-${itemIndex}-${formIndex}`,index:lessons.length,level:topic.level,topic:topic.name,caption:topic.caption,spanish,arabic,hint:LEVELS[topic.level].hint});
 }));
