const numerals=n=>String(n).replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[Number(d)]);
const storage={get(k,fallback){try{const v=JSON.parse(localStorage.getItem('hola-'+k));return v??fallback}catch{return fallback}},set(k,v){try{localStorage.setItem('hola-'+k,JSON.stringify(v))}catch{}}};
let completed=new Set(storage.get('completed',[]));
let saved=new Set(storage.get('saved',[]));
let completedToday=new Set(storage.get('today',[]));
let todayStamp=new Date().toLocaleDateString('en-CA');
if(storage.get('todayStamp','')!==todayStamp){completedToday=new Set();storage.set('today',[]);storage.set('todayStamp',todayStamp)}
let activeView='learn',currentIndex=0,selectedLevel=0,libraryFilter='all',searchTerm='',shownCount=30,toastTimer,recorder=null,recordedBlob=null,recordedUrl=null,timerInterval=null,recordStarted=0;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function current(){return lessons[currentIndex]}
function levelEntries(level){return lessons.filter(x=>x.level===level)}
function updateProgress(){const done=completed.size,percent=Math.min(100,done/20);$('#doneCount').textContent=numerals(done);$('#journeyProgress').style.width=`${percent}%`;let lvl=0;for(let i=0;i<4;i++){if(done>=(i+1)*500)lvl=Math.min(i+1,3)}$('#levelName').textContent=LEVELS[lvl].title;const today=Math.min(completedToday.size,5),daily=Math.min(100,today/5*100);$('#todayDone').textContent=numerals(today);$('#dailyPercent').textContent=numerals(Math.round(daily))+'٪';$('#dailyProgress').style.width=`${daily}%`;const days=storage.get('streak',0);$('#topStreak').textContent=numerals(days);$('#streakLabel').textContent=days?`سلسلة رائعة: ${numerals(days)} يوم`:'يوم جديد، بداية جميلة!';}
function renderLesson(){const l=current();selectedLevel=l.level;$('#lessonLevel').textContent=`${LEVELS[l.level].code} · ${LEVELS[l.level].name}`;$('#lessonTopic').textContent=l.topic;$('#lessonNumber').textContent=`الجملة ${numerals(l.index+1).padStart(2,'٠')}`;$('#spanishSentence').textContent=l.spanish;$('#arabicSentence').textContent=l.arabic;$('#sentenceHint').textContent=l.hint;$('#sceneCaption').textContent=l.caption;$('#saveButton').classList.toggle('saved',saved.has(l.id));$('#saveButton').textContent=saved.has(l.id)?'♥':'♡';$$('.level-tab').forEach(b=>b.classList.toggle('selected',Number(b.dataset.level)===l.level));const nextLevel=LEVELS[l.level];$('#crumbTitle').textContent=activeView==='learn'?'تعلّم اليوم':activeView==='library'?'مكتبة الجمل':'المحفوظات';}
function goTo(index){currentIndex=(index+lessons.length)%lessons.length;renderLesson()}
function markComplete(){const l=current();if(!completed.has(l.id)){completed.add(l.id);completedToday.add(l.id);storage.set('completed',[...completed]);storage.set('today',[...completedToday]);if(completedToday.size===1){const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const prev=yesterday.toLocaleDateString('en-CA');const last=storage.get('lastDay','');let streak=storage.get('streak',0);if(last===prev)streak++;else if(last!==todayStamp)streak=1;storage.set('streak',streak);storage.set('lastDay',todayStamp)}updateProgress()}}
function setView(view){activeView=view;$$('.view').forEach(v=>v.classList.remove('active'));const section=$(`#${view}View`);if(section)section.classList.add('active');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumbTitle').textContent=view==='learn'?'تعلّم اليوم':view==='library'?'مكتبة الجمل':'المحفوظات';if(view==='library')renderLibrary();if(view==='saved')renderSaved();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function toggleSaved(id){if(saved.has(id))saved.delete(id);else saved.add(id);storage.set('saved',[...saved]);renderLesson();if(activeView==='library')renderLibrary();if(activeView==='saved')renderSaved()}
function makePhraseRow(l){const row=document.createElement('article');row.className='phrase-row';const num=document.createElement('span');num.className='phrase-num';num.textContent=numerals(l.index+1).padStart(4,'٠');const content=document.createElement('div');content.className='phrase-row-content';const es=document.createElement('div');es.className='phrase-row-spanish';es.lang='es';es.textContent=l.spanish;const ar=document.createElement('div');ar.className='phrase-row-arabic';ar.textContent=l.arabic;content.append(es,ar);const tag=document.createElement('span');tag.className='phrase-row-tag';tag.textContent=LEVELS[l.level].code;const actions=document.createElement('div');actions.className='phrase-row-actions';const open=document.createElement('button');open.textContent='↗';open.title='افتح هذه الجملة';open.addEventListener('click',()=>{currentIndex=l.index;renderLesson();setView('learn')});const fav=document.createElement('button');fav.textContent=saved.has(l.id)?'♥':'♡';fav.classList.toggle('saved',saved.has(l.id));fav.title='حفظ';fav.addEventListener('click',()=>toggleSaved(l.id));actions.append(open,fav);row.append(num,content,tag,actions);return row}
function renderLibrary(){let found=lessons.filter(l=>(libraryFilter==='all'||l.level===Number(libraryFilter))&&(!searchTerm||`${l.spanish} ${l.arabic} ${l.topic}`.toLocaleLowerCase().includes(searchTerm.toLocaleLowerCase())));$('#resultCount').textContent=`${numerals(found.length)} جملة`;const list=$('#phraseList');list.replaceChildren(...found.slice(0,shownCount).map(makePhraseRow));$('#loadMore').style.display=found.length>shownCount?'inline-block':'none';if(!found.length){const empty=document.createElement('div');empty.className='empty-state show';empty.innerHTML='<span>⌕</span><h2>لا توجد نتائج</h2><p>جرّب كلمة أخرى أو اختر مستوى مختلفًا.</p>';list.append(empty)}}
function renderSaved(){const data=lessons.filter(l=>saved.has(l.id));const list=$('#savedList');list.replaceChildren(...data.map(makePhraseRow));$('#emptySaved').classList.toggle('show',data.length===0);list.style.display=data.length?'grid':'none'}
function startLevel(level){const first=lessons.findIndex(l=>l.level===level);if(first>=0)goTo(first)}
function speakCurrent(){if(!('speechSynthesis'in window)){toast('لا يتوفر نطق محلي على هذا الجهاز. اقرأ العبارة ثم سجّل صوتك.');return}const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('es-es')&&v.localService);if(!voice){toast('لا يوجد صوت إسباني محلي مثبّت. لا نستخدم أي صوت عبر الإنترنت.');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(current().spanish);utterance.lang='es-ES';utterance.voice=voice;utterance.rate=.82;speechSynthesis.speak(utterance)}
function formatTime(seconds){return numerals(String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'))}
async function toggleRecording(){if(recorder?.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('التسجيل الصوتي غير مدعوم في هذا المتصفح. جرّب Chrome أو Safari.');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const types=['audio/webm;codecs=opus','audio/webm','audio/mp4'];const mime=types.find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());clearInterval(timerInterval);recordedBlob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl=URL.createObjectURL(recordedBlob);$('#playRecording').disabled=false;$('#discardRecording').disabled=false;$('#recordStatus').textContent='تم التسجيل — أحسنت!';$('#recordButton').classList.remove('recording');$('#recordButton').setAttribute('aria-label','ابدأ التسجيل');markComplete()};recorder.start();recordStarted=Date.now();$('#recordButton').classList.add('recording');$('#recordButton').setAttribute('aria-label','أوقف التسجيل');$('#recordStatus').textContent='جارٍ التسجيل... اضغط للإيقاف';$('#playRecording').disabled=true;$('#discardRecording').disabled=true;$('#recordTimer').textContent='٠٠:٠٠';timerInterval=setInterval(()=>{const sec=Math.floor((Date.now()-recordStarted)/1000);$('#recordTimer').textContent=formatTime(sec);if(sec>=30)recorder.stop()},250)}catch(e){toast(e.name==='NotAllowedError'?'اسمح باستخدام الميكروفون لبدء التسجيل.':'تعذّر الوصول إلى الميكروفون. يمكنك التمرّن بصوت عالٍ دون تسجيل.');$('#recordStatus').textContent='اضغط للتسجيل'}}
function discardRecording(){if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl=null;recordedBlob=null;$('#playRecording').disabled=true;$('#discardRecording').disabled=true;$('#recordStatus').textContent='اضغط للتسجيل';$('#recordTimer').textContent='٠٠:٠٠'}

$$('.nav-item').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));
$$('[data-go]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.go.replace('View',''))));
$('#nextButton').addEventListener('click',()=>{markComplete();goTo(currentIndex+1)});
$('#prevButton').addEventListener('click',()=>goTo(currentIndex-1));
$('#saveButton').addEventListener('click',()=>toggleSaved(current().id));
$('#speakButton').addEventListener('click',speakCurrent);
$('#recordButton').addEventListener('click',toggleRecording);
$('#discardRecording').addEventListener('click',discardRecording);
$('#playRecording').addEventListener('click',()=>{if(recordedUrl){const audio=new Audio(recordedUrl);audio.play().catch(()=>toast('تعذّر تشغيل التسجيل على هذا الجهاز.'))}});
$$('.level-tab').forEach(button=>button.addEventListener('click',()=>startLevel(Number(button.dataset.level))));
$$('.nav-item').forEach((button,index)=>button.addEventListener('keydown',e=>{if(e.key==='Enter')setView(button.dataset.view)}));
$$('#libraryFilters .filter-pill').forEach(button=>button.addEventListener('click',()=>{libraryFilter=button.dataset.filter;shownCount=30;$$('#libraryFilters .filter-pill').forEach(b=>b.classList.toggle('active',b===button));renderLibrary()}));
$('#searchInput').addEventListener('input',e=>{searchTerm=e.target.value;shownCount=30;renderLibrary()});
$('#loadMore').addEventListener('click',()=>{shownCount+=30;renderLibrary()});
$('#dailyGoalButton').addEventListener('click',()=>toast(`هدفك اليوم ${numerals(5)} جمل — أنت قادر عليها!`));
$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#scene').addEventListener('click',e=>{if(e.target.closest('.scene-play')){const scene=$('#scene');scene.classList.remove('scene-replay');void scene.offsetWidth;scene.classList.add('scene-replay');toast('مشهد بصري توضيحي محفوظ محليًا — بلا فيديو خارجي.')}});
window.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();setView('library');$('#searchInput').focus()}if(e.key==='Escape')$('#sidebar').classList.remove('open');if(activeView==='learn'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){if(e.key==='ArrowLeft'){e.preventDefault();markComplete();goTo(currentIndex+1)}if(e.key==='ArrowRight'){e.preventDefault();goTo(currentIndex-1)}}});
window.addEventListener('online',()=>toast('اتصالك عاد — التطبيق لا يحتاجه للدروس.'));
window.addEventListener('offline',()=>toast('أنت الآن دون اتصال — يمكنك متابعة جميع الدروس.'));
if('serviceWorker'in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(()=>{}).catch(()=>{}))}
$('#todayLabel').textContent=new Intl.DateTimeFormat('ar',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
renderLesson();updateProgress();
console.assert(lessons.length===2000,`Expected 2000 lessons, got ${lessons.length}`);

