ize:10px}.streak-pill:first-letter{color:#c28d2a}.avatar{width:31px;height:31px;border:0;border-radius:50%;background:#e8eee5;color:#45604d;font-weight:600}.content-wrap{width:min(100%,1170px);padding:37px 43px 32px;margin:0 auto;flex:1}.view{display:none}.view.active{display:block}.welcome-row,.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:25px}.eyebrow{font:600 9px var(--latin);letter-spacing:2px;color:#76917e;display:flex;align-items:center;gap:8px}.eyebrow-line{width:19px;height:1px;background:#87a48c}.welcome-row h1,.page-heading h1{font-size:27px;line-height:1.45;letter-spacing:-.7px;margin:7px 0 3px;font-weight:600}.welcome-row h1 em,.page-heading h1 em{font-weight:500;color:#64816c;font-style:normal}.welcome-row p,.page-heading p{margin:0;color:#979b93;font-size:11px}.date-chip{display:flex;align-items:center;gap:9px;background:#fff;border:1px solid var(--line);padding:9px 13px;border-radius:9px;margin-bottom:2px}.date-chip>span{font-size:23px;color:#d6a440}.date-chip b,.date-chip small{display:block}.date-chip b{font-size:10px}.date-chip small{font-size:9px;color:#9b9f97;margin-top:3px}.level-tabs{display:flex;align-items:center;gap:7px;border-bottom:1px solid #e8e8e1;margin-bottom:18px}.level-tab{background:transparent;border:0;color:#92968e;padding:0 10px 12px;font-size:10px;display:flex;align-items:center;gap:7px;position:relative}.level-tab span{font:700 10px var(--latin);color:#90968e;background:#edeee8;border-radius:5px;padding:4px 5px}.level-tab.selected{color:var(--green);font-weight:600}.level-tab.selected span{background:#e2eee4;color:#386648}.level-tab.selected:after{content:'';position:absolute;height:2px;background:#426d52;bottom:-1px;left:7px;right:7px}.tabs-spacer{flex:1}.level-note{color:#a6a8a0;font-size:9px;padding-bottom:12px}.lesson-layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(230px,.82fr);gap:17px;align-items:start}.lesson-card,.practice-card,.progress-card{background:#fff