const TOPIC_TRANSLATIONS={
 'في المقهى':'en la cafetería','في المدينة':'en la ciudad','في المنزل':'en casa','التسوّق':'de compras','التعارف':'al conocer a alguien','روتين الصباح':'la rutina de la mañana','السفر بالقطار':'viajar en tren','في الفندق':'en el hotel','الطعام الإسباني':'la comida española','التعرّف على الناس':'conocer gente','الصحة والعافية':'la salud y el bienestar','العمل والدراسة':'el trabajo y los estudios','السكن والحي':'la vivienda y el barrio','الطقس والطبيعة':'el tiempo y la naturaleza','المواصلات والسفر':'el transporte y los viajes','الرأي والنقاش':'las opiniones y el debate','الإعلام والتقنية':'los medios y la tecnología','الثقافة والمجتمع':'la cultura y la sociedad','البيئة والاستدامة':'el medioambiente y la sostenibilidad','الخطط والأهداف':'los planes y los objetivos'
};
const PHRASES=[];
TOPICS.forEach((topic,topicIndex)=>topic.items.forEach((item,itemIndex)=>{
 const level=topic.level;
 FRAMES[level].forEach((frame,frameIndex)=>PHRASES.push({
  id:PHRASES.length+1,level,topic:topic.name,topicIndex,anchor:item[0],
  es:frame[0].replaceAll('{es}',item[0]),ar:frame[1].replaceAll('{ar}',item[1]),
  hint:`${LEVELS[level].hint} موضوع العبارة: ${topic.name}.`,caption:topic.caption
 }));
}));
if(PHRASES.length!==2000) throw new Error(`Expected exactly 2,000 phrases; created ${PHRASES.length}`);

const STORE_KEY='hola-es-progress-v1';
const initialState={completed:[],saved:[],lastId:1,daily:{date:'',count:0},streak:{date:'',count:0}};
function loadState(){try{const value=JSON.parse(localStorage.getItem(STORE_KEY)||'{}');return {...initialState,...value,daily:{...initialState.daily,...value.daily},streak:{...initialState.streak,...value.streak}}}catch{return {...initialState}}}
let state=loadState();
const $=id=>document.getElementById(id);
const arabicNumber=value=>Number(value||0).toLocaleString('ar-EG');
const todayKey=()=>new Date().toISOString().slice(0,10);
let currentId=Math.min(PHRASES.length,Math.max(1,Number(state.lastId)||1));
let selectedLevel=PHRASES[currentId-1].level;
let activeView='learn',libraryFilter='all',searchTerm='',visibleCount=60,recording=null,mediaRecorder=null,recordedUrl='',recordedBlob=null,recordStart=0,timerHandle=null,toastHandle=null;
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state))}catch{notify('تعذّر حفظ التقدم في هذا المتصفح.')};updateProgress()}
function levelText(level){return `${LEVELS[level].code} · ${LEVELS[level].name}`}
function getPhrase(id){return PHRASES[Math.min(PHRASES.length,Math.max(1,id))-1]}
function updatePhrase(){
 const phrase=getPhrase(currentId);selectedLevel=phrase.level;state.lastId=currentId;
 $('lessonLevel').textContent=levelText(phrase.level);$('lessonTopic').textContent=phrase.topic;
 $('lessonNumber').textContent=`الجملة ${arabicNumber(String(currentId).padStart(2,'0'))}`;
 $('spanishSentence').textContent=phrase.es;$('arabicSentence').textContent=phrase.ar;$('sentenceHint').textContent=phrase.hint;
 $('sceneCaption').textContent=phrase.caption;
 document.querySelectorAll('.level-tab').forEach(button=>button.classList.toggle('selected',Number(button.dataset.level)===phrase.level));
 const saved=state.saved.includes(currentId);$('saveButton').textContent=saved?'♥':'♡';$('saveButton').classList.toggle('saved',saved);$('saveButton').setAttribute('aria-label',saved?'إزالة الجملة من المحفوظات':'حفظ الجملة');
 $('prevButton').disabled=currentId===1;$('nextButton').disabled=currentId===PHRASES.length;
 persist();
}
function updateProgress(){
 const completed=new Set(state.completed);const count=completed.size;const percent=Math.min(100,count/PHRASES.length*100);
 if($('doneCount'))$('doneCount').textContent=arabicNumber(count);
 if($('journeyProgress'))$('journeyProgress').style.width=`${percent}%`;
 const level=completed.size?getPhrase([...completed].sort((a,b)=>a-b).at(-1)).level:0;
 if($('levelName'))$('levelName').textContent=LEVELS[level].title;
 const today=todayKey();if(state.daily.date!==today)state.daily={date:today,count:0};
 const dailyPercent=Math.min(100,state.daily.count/5*100);
 if($('todayDone'))$('todayDone').textContent=arabicNumber(state.daily.count);
 if($('dailyPercent'))$('dailyPercent').textContent=`${arabicNumber(Math.round(dailyPercent))}٪`;
 if($('dailyProgress'))$('dailyProgress').style.width=`${dailyPercent}%`;
 const streak=state.streak.count||0;
 if($('topStreak'))$('topStreak').textContent=arabicNumber(streak);
 if($('streakLabel'))$('streakLabel').textContent=streak?`أيام متتالية رائعة: ${arabicNumber(streak)}`:'يوم جديد، بداية جميلة!';
}
function markCompleted(id){
 if(!state.completed.includes(id)){state.completed.push(id);state.completed.sort((a,b)=>a-b)}
 const today=todayKey();if(state.daily.date!==today)state.daily={date:today,count:0};
 if(state.daily.lastId!==id){state.daily.count=Math.min(5,state.daily.count+1);state.daily.lastId=id}
 const previous=new Date(Date.now()-86400000).toISOString().slice(0,10);
 if(state.streak.date!==today){state.streak.count=state.streak.date===previous?state.streak.count+1:1;state.streak.date=today}
 persist();
}
function notify(message){const toast=$('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastHandle);toastHandle=setTimeout(()=>toast.classList.remove('show'),2500)}
function goToPhrase(id){currentId=Math.min(PHRASES.length,Math.max(1,id));updatePhrase();showView('learn');window.scrollTo({top:0,behavior:'smooth'})}
function renderPhraseRow(phrase){
 const row=document.createElement('article');row.className='phrase-row';
 const text=document.createElement('div');text.className='phrase-row-text';
 const spanish=document.createElement('b');spanish.className='phrase-row-spanish';spanish.lang='es';spanish.textContent=phrase.es;
 const arabic=document.createElement('span');arabic.className='phrase-row-arabic';arabic.textContent=phrase.ar;
 text.append(spanish,arabic);
 const tag=document.createElement('span');tag.className='phrase-row-tag';tag.textContent=LEVELS[phrase.level].code;
 const actions=document.createElement('div');actions.className='phrase-row-actions';
 const speak=document.createElement('button');speak.type='button';speak.className='phrase-row-button';speak.textContent='🔊';speak.title='استمع';speak.setAttribute('aria-label','استمع إلى العبارة');speak.addEventListener('click',()=>speakText(phrase.es));
 const open=document.createElement('button');open.type='button';open.className='phrase-row-button';open.textContent='↗';open.title='افتح الدرس';open.setAttribute('aria-label','افتح العبارة في الدرس');open.addEventListener('click',()=>goToPhrase(phrase.id));
 actions.append(speak,open);row.append(text,tag,actions);return row;
}
function filteredPhrases(){return PHRASES.filter(phrase=>(libraryFilter==='all'||phrase.level===Number(libraryFilter))&&(!searchTerm||`${phrase.es} ${phrase.ar} ${phrase.topic}`.toLocaleLowerCase().includes(searchTerm)))}
function renderLibrary(){
 const list=$('phraseList');if(!list)return;const results=filteredPhrases();list.replaceChildren();results.slice(0,visibleCount).forEach(phrase=>list.append(renderPhraseRow(phrase)));
 $('resultCount').textContent=`${arabicNumber(results.length)} جملة`;$('loadMore').hidden=results.length<=visibleCount;
}
function renderSaved(){
 const list=$('savedList');if(!list)return;const phrases=state.saved.map(getPhrase).filter(Boolean);list.replaceChildren();phrases.forEach(phrase=>list.append(renderPhraseRow(phrase)));
 $('emptySaved').hidden=phrases.length>0;
}
function showView(name){
 const viewId=name.endsWith('View')?name:`${name}View`;const view=$(viewId);if(!view)return;
 activeView=viewId;document.querySelectorAll('.view').forEach(item=>item.classList.toggle('active',item===view));
 document.querySelectorAll('.nav-item').forEach(button=>button.classList.toggle('active',button.dataset.view===viewId.replace('View','')));
 const labels={learnView:'تعلّم اليوم',libraryView:'مكتبة الجمل',savedView:'المحفوظات'};$('crumbTitle').textContent=labels[viewId]||labels.learnView;
 if(viewId==='libraryView')renderLibrary();if(viewId==='savedView')renderSaved();$('sidebar').classList.remove('open');
}
function speakText(text){
 if(!('speechSynthesis' in window)){notify('النطق الصوتي غير متاح في هذا المتصفح.');return}
 window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='es-ES';utterance.rate=.82;window.speechSynthesis.speak(utterance);
}
function setRecordingUi(recordingNow){$('recordButton').classList.toggle('recording',recordingNow);$('recordButton').setAttribute('aria-label',recordingNow?'أوقف التسجيل':'ابدأ التسجيل');$('recordStatus').textContent=recordingNow?'جارٍ التسجيل…':'اضغط للتسجيل'}
async function startRecording(){
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('التسجيل يحتاج إلى اتصال آمن (HTTPS) ومتصفح يدعمه.');return}
 try{
  const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordedBlob=null;const chunks=[];
  mediaRecorder=new MediaRecorder(stream);mediaRecorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data)};
  mediaRecorder.onstop=()=>{recordedBlob=new Blob(chunks,{type:mediaRecorder.mimeType||'audio/webm'});if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl=URL.createObjectURL(recordedBlob);$('playRecording').disabled=false;$('discardRecording').disabled=false;stream.getTracks().forEach(track=>track.stop());$('recordStatus').textContent='اكتمل التسجيل — أحسنت!';notify('تم حفظ التسجيل مؤقتًا على جهازك.')};
  mediaRecorder.start();recordStart=Date.now();setRecordingUi(true);$('playRecording').disabled=true;$('discardRecording').disabled=true;
  timerHandle=setInterval(()=>{const seconds=Math.floor((Date.now()-recordStart)/1000);$('recordTimer').textContent=`${arabicNumber(String(Math.floor(seconds/60)).padStart(2,'0'))}:${arabicNumber(String(seconds%60).padStart(2,'0'))}`},250);
 }catch(error){notify(error.name==='NotAllowedError'?'يرجى السماح باستخدام الميكروفون لبدء التسجيل.':'تعذّر الوصول إلى الميكروفون.')}
}
function stopRecording(){if(mediaRecorder?.state==='recording'){mediaRecorder.stop();clearInterval(timerHandle);setRecordingUi(false);markCompleted(currentId)}}
function discardRecording(){if(mediaRecorder?.state==='recording')stopRecording();if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl='';recordedBlob=null;$('playRecording').disabled=true;$('discardRecording').disabled=true;$('recordTimer').textContent='٠٠:٠٠';$('recordStatus').textContent='اضغط للتسجيل';notify('حُذف التسجيل.')}

function bindEvents(){
 document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
 document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.go)));
 document.querySelectorAll('.level-tab').forEach(button=>button.addEventListener('click',()=>{const level=Number(button.dataset.level);const first=PHRASES.find(phrase=>phrase.level===level);if(first)goToPhrase(first.id)}));
 $('nextButton').addEventListener('click',()=>{markCompleted(currentId);goToPhrase(currentId+1)});
 $('prevButton').addEventListener('click',()=>goToPhrase(currentId-1));
 $('saveButton').addEventListener('click',()=>{const index=state.saved.indexOf(currentId);if(index>=0){state.saved.splice(index,1);notify('أزيلت الجملة من المحفوظات.')}else{state.saved.push(currentId);notify('أضيفت الجملة إلى المحفوظات.')}persist();updatePhrase();if(activeView==='savedView')renderSaved()});
 $('speakButton').addEventListener('click',()=>speakText(getPhrase(currentId).es));
 $('recordButton').addEventListener('click',()=>mediaRecorder?.state==='recording'?stopRecording():startRecording());
 $('playRecording').addEventListener('click',()=>{if(recordedUrl){const audio=new Audio(recordedUrl);audio.play().catch(()=>notify('تعذّر تشغيل التسجيل.'))}});
 $('discardRecording').addEventListener('click',discardRecording);
 $('searchInput').addEventListener('input',event=>{searchTerm=event.target.value.trim().toLocaleLowerCase();visibleCount=60;renderLibrary()});
 document.querySelectorAll('#libraryFilters [data-filter]').forEach(button=>button.addEventListener('click',()=>{libraryFilter=button.dataset.filter;visibleCount=60;document.querySelectorAll('#libraryFilters [data-filter]').forEach(item=>item.classList.toggle('active',item===button));renderLibrary()}));
 $('loadMore').addEventListener('click',()=>{visibleCount+=60;renderLibrary()});
 $('dailyGoalButton').addEventListener('click',()=>notify(`أنجزت ${arabicNumber(state.daily.count||0)} من ٥ جمل اليوم. تابع على هذا الإيقاع!`));
 $('menuToggle').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
 document.addEventListener('keydown',event=>{
  const target=event.target;if(target instanceof HTMLInputElement||target instanceof HTMLTextAreaElement)return;
  if(event.key==='ArrowLeft'){event.preventDefault();markCompleted(currentId);goToPhrase(currentId+1)}
  else if(event.key==='ArrowRight'){event.preventDefault();goToPhrase(currentId-1)}
  else if(event.key==='/'&&activeView==='libraryView'){event.preventDefault();$('searchInput').focus()}
 });
 if('serviceWorker' in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
}
function initialize(){
 const now=new Date();$('todayLabel').textContent=new Intl.DateTimeFormat('ar',{weekday:'long',day:'numeric',month:'long'}).format(now);
 const date=todayKey();if(state.daily.date!==date)state.daily={date,count:0};
 updateProgress();updatePhrase();bindEvents();
}
initialize();

