function freshState(){return {done:[],saved:[],today:todayKey(),todayDone:[],streak:0,lastActive:'',dailyGoal:5,currentId:0}}
function loadState(){
 try{
  const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');
