function updateStreak(){
 const today=todayKey();
 if(state.lastActive===today)return;
 if(state.lastActive){const previous=new Date(`${state.lastActive}T00:00:00`);const current=new Date(`${today}T00:00:00`);const gap=Math.round((current-previous)/86400000);state.streak=gap===1?state.streak+1:gap>1?1:state.streak}
 else state.streak=1;
 state.lastActive=today;
}
function markDone(id){
 if(!state.done.includes(id))state.done.push(id);
